    """
def is_infinite(x: Any, y: Any) -> object {
    (x, y) = (x, y) if (x < y) else (y, x);
    while (x != y) {
        y -= x;
        x *= 2;
        if (x > y) {
            return True;
        }
    }
    return False;
}

