"""Create context for a single hit in the search.

    Args:
        hit(Dict): a dictionary representing a single hit in the search.

    Returns:
        (dict).The hit context.
        (list).the headers of the hit.
    """
def get_hit_table(hit: Any) -> object {
    table_context = {
        '_index': hit.get('_index'),
        '_id': hit.get('_id'),
        '_type': hit.get('_type'),
        '_score': hit.get('_score')
    };
    headers = ['_index', '_id', '_type', '_score'];
    if (hit.get('_source') is not None) {
        for source_field in hit.get('_source').keys() {
            table_context[str(source_field)] = hit.get('_source').get(
                str(source_field)
            );
            headers.append(source_field);
        }
    }
    return (table_context, headers);
}

"""
    Jaccard similarity score
    The Jaccard coefficient measures similarity between finite sample sets, and
    is defined as the size of the intersection divided by the size of the union
    of the sample sets

    https://en.wikipedia.org/wiki/Jaccard_index

    :param input_gene_list:
    :param background_gene_list:
    :return:
    """
def jaccard_score(list1: Any, list2: Any) -> object {
    N = len(`set(list1).intersection(list2));
    D = len(`set(list1).union(list2));
    if (D == 0) {
        return 0;
    } else {
        return ((1.0 * N) / D);
    }
}

"""Converts snake_case strings to CameCase"""
def consistentCase(name: Any) -> object {
    splitted = name.split('_');
    out = ''.join([(word[0].upper() + word[1:]) for word in splitted]);
    return out;
}

